# Regenerates data_meta_reml_weights.csv and ref_meta_reml_weights.csv (drmTMB 0.8.1, meta_V, REML = TRUE, weights).
# Run from this directory: R_LIBS=~/drm_campaign_20261108/Rlib Rscript make_reference.R   (drmTMB 0.8.1 on Totoro; reads ../meta_v_reml/data_meta_reml.csv)
suppressMessages(library(drmTMB))
d <- read.csv("../meta_v_reml/data_meta_reml.csv"); d$g <- factor(d$g)
set.seed(7)                                   # the vectors depend on this seed after reading the CSV
d$w  <- runif(nrow(d), 0.4, 2.5)              # continuous weights
d$wi <- sample(1:3, nrow(d), TRUE)            # integer weights
d$w1 <- 1                                     # unit weights
write.csv(d, "data_meta_reml_weights.csv", row.names = FALSE)
rows <- list()
add <- function(cell, fit) {
  co <- summary(fit)$coefficients
  rows[[length(rows) + 1]] <<- data.frame(cell = cell, key = "logLik", est = as.numeric(logLik(fit)), se = NA)
  rows[[length(rows) + 1]] <<- data.frame(cell = cell, key = rownames(co), est = co[, "estimate"], se = co[, "std_error"])
}
for (wn in c("w", "wi", "w1")) {
  dd <- d; dd$ww <- dd[[wn]]
  add(paste0("metaw_reml_", wn), drmTMB(bf(yi ~ x1 + meta_V(V = vi), sigma ~ 1), family = gaussian(), data = dd, weights = ww, REML = TRUE))
  add(paste0("metaw_ml_", wn),   drmTMB(bf(yi ~ x1 + meta_V(V = vi), sigma ~ 1), family = gaussian(), data = dd, weights = ww, REML = FALSE))
}
add("meta_reml_unweighted", drmTMB(bf(yi ~ x1 + meta_V(V = vi), sigma ~ 1), family = gaussian(), data = d, REML = TRUE))
# Information only, not pinned (Julia refuses weights with meta_V + (1 | g)): R fits it.
for (wn in c("w", "wi")) {
  dd <- d; dd$ww <- dd[[wn]]
  for (reml in c(TRUE, FALSE)) {
    f <- tryCatch(drmTMB(bf(yi ~ x1 + (1 | g) + meta_V(V = vi), sigma ~ 1), family = gaussian(), data = dd, weights = ww, REML = reml),
                  error = function(e) NULL)
    if (!is.null(f)) cat(sprintf("INFO meta_V + (1|g) weights=%s REML=%s logLik=%.10f\n", wn, reml, as.numeric(logLik(f))))
    else cat("INFO meta_V + (1|g) weights", wn, "REML", reml, "R refused\n")
  }
}
out <- do.call(rbind, rows)
hdr <- c(sprintf("# %s; R %s; TMB %s; Matrix %s; %s", paste0("drmTMB ", as.character(packageVersion("drmTMB"))),
                 paste(R.version$major, R.version$minor, sep = "."), as.character(packageVersion("TMB")),
                 as.character(packageVersion("Matrix")), R.version$platform),
         "# generated by make_reference.R (set.seed(7) after reading data_meta_reml.csv); meta_V(V = vi), sigma ~ 1")
writeLines(hdr, "ref_meta_reml_weights.csv")
suppressWarnings(write.table(out, "ref_meta_reml_weights.csv", sep = ",", row.names = FALSE, append = TRUE, qmethod = "double"))
